// ── FORMAT JSON PAYLOAD FOR TARGET CRM API ──────────────────────────
const body = $input.item.json.body;

// Map incoming fields to Salesforce-compatible CRM schema
const payload = {
  account: {
    name: body.company_name,
    billing_country: body.country_iso,
    phone: body.phone_e164 || null,
    type: 'Customer',
    industry: 'Technology'
  },
  contact: {
    email: body.contact_email,
    phone: body.phone_e164 || null,
    account_name: body.company_name
  },
  opportunity: {
    name: `${body.company_name} — ${body.plan_tier} Plan`,
    stage: 'Closed Won',
    close_date: body.signup_date || new Date().toISOString().split('T')[0],
    amount: parseFloat(body.annual_contract_usd),
    plan_tier: body.plan_tier,
    type: 'New Business',
    lead_source: 'API Integration',
    migration_batch: 'NEXACLOUD_2026_11'
  },
  metadata: {
    source_system: 'Legacy CRM Migration',
    submitted_at: new Date().toISOString(),
    sync_version: '1.0.0'
  }
};

return [{ json: { payload, original: body } }];

